From 427b5f74f62e59607dc50c94cd506aa5413f7f6b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 04:06:46 +0100
Subject: [PATCH] applets/pager: sort activities by name

The activity pager listed activities in the order the activity manager
returned them, so "Proj 10" came before "Proj 2". Sort them by name with
a numeric-aware collator, like the activity settings already do.

BUG: 404149
---
 applets/pager/pagermodel.cpp | 21 ++++++++++++++-------
 1 file changed, 14 insertions(+), 7 deletions(-)

diff --git a/applets/pager/pagermodel.cpp b/applets/pager/pagermodel.cpp
index 6e476f3d15..621b021b27 100644
--- a/applets/pager/pagermodel.cpp
+++ b/applets/pager/pagermodel.cpp
@@ -14,6 +14,7 @@
 #include <waylandtasksmodel.h>
 #include <windowtasksmodel.h>

+#include <QCollator>
 #include <QDBusConnection>
 #include <QDBusMessage>
 #include <QDBusPendingCall>
@@ -52,6 +53,7 @@ public:
     static ActivityInfo *activityInfo;
     QMetaObject::Connection activityNumberConn;
     QMetaObject::Connection activityNamesConn;
+    QStringList sortedActivities;

     static VirtualDesktopInfo *virtualDesktopInfo;
     QMetaObject::Connection virtualDesktopNumberConn;
@@ -219,7 +221,7 @@ QVariant PagerModel::data(const QModelIndex &index, int role) const
         if (d->pagerType == VirtualDesktops) {
             return d->virtualDesktopInfo->desktopNames().at(index.row());
         } else {
-            QString activityId = d->activityInfo->runningActivities().at(index.row());
+            QString activityId = d->sortedActivities.at(index.row());
             return d->activityInfo->activityName(activityId);
         }
     } else if (role == TasksModel) {
@@ -363,7 +365,7 @@ int PagerModel::currentPage() const
             !d->screenName.isEmpty() ? d->virtualDesktopInfo->currentDesktopByScreenName(d->screenName) : d->virtualDesktopInfo->currentDesktop();
         return d->virtualDesktopInfo->desktopIds().indexOf(desktopId);
     } else {
-        return d->activityInfo->runningActivities().indexOf(d->activityInfo->currentActivity());
+        return d->sortedActivities.indexOf(d->activityInfo->currentActivity());
     }
 }

@@ -430,12 +432,18 @@ void PagerModel::refresh()
         }
     } else {
         int activityIndex = 0;
-        const QStringList &runningActivities = d->activityInfo->runningActivities();
+        d->sortedActivities = d->activityInfo->runningActivities();
+
+        QCollator collator;
+        collator.setNumericMode(true);
+        std::sort(d->sortedActivities.begin(), d->sortedActivities.end(), [this, &collator](const QString &a, const QString &b) {
+            return collator.compare(d->activityInfo->activityName(a), d->activityInfo->activityName(b)) < 0;
+        });

         for (auto windowModel : std::as_const(d->windowModels)) {
             windowModel->setVirtualDesktop();

-            windowModel->setActivity(runningActivities.at(activityIndex));
+            windowModel->setActivity(d->sortedActivities.at(activityIndex));
             ++activityIndex;
         }
     }
@@ -502,10 +510,9 @@ void PagerModel::changePage(int page)
                 d->virtualDesktopInfo->requestActivate(desktopId);
             }
         } else {
-            const QStringList &runningActivities = d->activityInfo->runningActivities();
-            if (page < runningActivities.length()) {
+            if (page < d->sortedActivities.length()) {
                 KActivities::Controller activitiesController;
-                activitiesController.setCurrentActivity(runningActivities.at(page));
+                activitiesController.setCurrentActivity(d->sortedActivities.at(page));
             }
         }
     }
